mapper.update:
UPDATE flight_reserve_member frm JOIN flight_reserve fr ON frm.flight_reno = fr.flight_reno SET frm.flight_start_payCheck = (CASE WHEN fr.flight_start_id IS NOT NULL
AND fr.flight_start_id IN
#{id}
THEN 'Y' ELSE frm.flight_start_payCheck END),
frm.flight_arr_payCheck = (CASE WHEN fr.flight_arr_id IS NOT NULL
AND fr.flight_arr_id IN
#{id}
THEN 'Y' ELSE frm.flight_arr_payCheck END) WHERE frm.flight_passport = #{flightPassport} AND frm.flight_reno = #{flightReno}

mapper.delete:
DELETE FROM flight_reserve_member
WHERE flight_reno = #{flightReno}
AND flight_mem_start_seatNum = #{flightMemStartSeatNum}
